dataset = [
    # --- BPMN-Diagrammbewertung ---
    {
        "question": 'Bewerte das folgende BPMN-Diagramm im XML-Format:\nxml\n<?xml version="1.0" encoding="UTF-8"?>\n<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL">\n <bpmn:collaboration id="Collab_1">\n <bpmn:participant id="Pool_Kunde" processRef="Process_Kunde" />\n <bpmn:participant id="Pool_Shop" processRef="Process_Shop" />\n </bpmn:collaboration>\n <bpmn:process id="Process_Kunde">\n <bpmn:task id="Task_Bestellen" name="Bestellen" />\n <bpmn:sequenceFlow id="Flow_1" sourceRef="Task_Bestellen" targetRef="Task_Bearbeiten" />\n </bpmn:process>\n <bpmn:process id="Process_Shop">\n <bpmn:task id="Task_Bearbeiten" name="Bestellung bearbeiten" />\n </bpmn:process>\n</bpmn:definitions>',
        "ground_truth": 'Analyse:\n1. Verletzung der Pool-Grenzen: Der Sequenzfluss (<bpmn:sequenceFlow id="Flow_1">) verbindet eine Task aus "Process_Kunde" direkt mit einer Task aus "Process_Shop".\n2. Widerspruch zur Autonomie: In BPMN repräsentieren unterschiedliche Prozesse/Pools unabhängige Organisationseinheiten, die ihren eigenen, isolierten Kontrollfluss haben.\n3. Falscher Elementtyp für externe Kommunikation: Sequenzflüsse beschreiben ausschließlich die interne zeitliche Abfolge. Für externe Interaktionen ist dieses Konstrukt syntaktisch und semantisch unzulässig.\nDidaktischer Hinweis: Ein Sequenzfluss (Sequence Flow) darf niemals die Grenzen eines Pools überschreiten. Die Interaktion zwischen zwei unabhängigen Pools (wie Kunde und Shop) muss zwingend über einen Nachrichtenfluss (Message Flow) modelliert werden.\nVerbesserungsvorschlag: Löschen Sie den sequenceFlow. Fügen Sie stattdessen einen <bpmn:messageFlow> auf der Ebene der <bpmn:collaboration> ein, der "Task_Bestellen" mit "Task_Bearbeiten" verbindet.',
    },
    {
        "question": 'Bewerte das folgende BPMN-Diagramm im XML-Format:\nxml\n<?xml version="1.0" encoding="UTF-8"?>\n<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL">\n <bpmn:process id="Process_1">\n <bpmn:exclusiveGateway id="XOR_Split" />\n <bpmn:sequenceFlow id="Flow_1" sourceRef="XOR_Split" targetRef="Task_A" />\n <bpmn:sequenceFlow id="Flow_2" sourceRef="XOR_Split" targetRef="Task_B" />\n <bpmn:parallelGateway id="AND_Join" />\n <bpmn:sequenceFlow id="Flow_3" sourceRef="Task_A" targetRef="AND_Join" />\n <bpmn:sequenceFlow id="Flow_4" sourceRef="Task_B" targetRef="AND_Join" />\n </bpmn:process>\n</bpmn:definitions>',
        "ground_truth": 'Analyse:\n1. Unzulässige Gateway-Paarung: Das Modell spaltet den Kontrollfluss mit einem exklusiven Gateway (<bpmn:exclusiveGateway>) auf, führt ihn aber mit einem parallelen Gateway (<bpmn:parallelGateway>) wieder zusammen.\n2. Verletzung der Token-Semantik: Der XOR-Split leitet exakt ein Token auf einen der beiden Pfade weiter (Entweder-Oder).\n3. Systemverklemmung (Deadlock): Der AND-Join wartet gemäß seiner Synchronisationsregel zwingend auf Tokens von allen eingehenden Sequenzflüssen. Da immer nur ein Token ankommen kann, blockiert der Prozess für immer.\nDidaktischer Hinweis: Aufspaltende und zusammenführende Gateways müssen in der BPMN logisch zueinander passen. Wenn sich alternative Pfade (XOR) wieder treffen, müssen sie mit einem exklusiven Merge-Gateway zusammengeführt werden, nicht mit einer parallelen Synchronisation.\nVerbesserungsvorschlag: Ändern Sie das <bpmn:parallelGateway id="AND_Join"> in ein <bpmn:exclusiveGateway>, damit das eintreffende Token den Zusammenführungspunkt ungehindert passieren kann.',
    },
    {
        "question": 'Bewerte das folgende BPMN-Diagramm im XML-Format:\nxml\n<?xml version="1.0" encoding="UTF-8"?>\n<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL">\n <bpmn:process id="Process_1">\n <bpmn:startEvent id="Start_1">\n <bpmn:incoming>Flow_Loop</bpmn:incoming>\n <bpmn:outgoing>Flow_1</bpmn:outgoing>\n </bpmn:startEvent>\n <bpmn:task id="Task_1" />\n <bpmn:sequenceFlow id="Flow_1" sourceRef="Start_1" targetRef="Task_1" />\n <bpmn:sequenceFlow id="Flow_Loop" sourceRef="Task_1" targetRef="Start_1" />\n </bpmn:process>\n</bpmn:definitions>',
        "ground_truth": 'Analyse:\n1. Eingehender Sequenzfluss an einem Startereignis: Das Startereignis ("Start_1") besitzt das Tag <bpmn:incoming>, welches auf den Sequenzfluss "Flow_Loop" verweist.\n2. Verletzung der Instanziierungsregel: Ein Startereignis ist der Ursprung eines Prozesses (es erzeugt das Prozess-Token). Es kann und darf logisch nicht das Ziel eines internen Prozessschrittes sein.\n3. Vermischung von Start und Iteration: Das Zurückspringen an den reinen Systemstart widerspricht der Lebenszyklus-Theorie eines Prozess-Tokens.\nDidaktischer Hinweis: Nach den strengen Regeln der BPMN 2.0 Spezifikation dürfen Startereignisse ausschließlich ausgehende Sequenzflüsse (<outgoing>) besitzen. Sie sind reine Quellen. (Analog dazu dürfen Endereignisse nur eingehende Flüsse besitzen).\nVerbesserungsvorschlag: Führen Sie den Flow_Loop nicht zum <bpmn:startEvent> zurück. Fügen Sie stattdessen ein exklusives Gateway direkt nach dem Startereignis ein und lassen Sie den Flow_Loop in dieses Gateway münden.',
    },
    {
        "question": 'Bewerte das folgende BPMN-Diagramm im XML-Format:\nxml\n<?xml version="1.0" encoding="UTF-8"?>\n<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL">\n <bpmn:process id="Process_1">\n <bpmn:task id="Task_1" name="Daten erfassen" />\n <bpmn:dataObjectReference id="DataObject_1" dataObjectRef="Data_1" />\n <bpmn:dataObject id="Data_1" />\n <bpmn:sequenceFlow id="Flow_1" sourceRef="Task_1" targetRef="DataObject_1" />\n </bpmn:process>\n</bpmn:definitions>',
        "ground_truth": 'Analyse:\n1. Kontrollfluss führt zu Datenobjekt: Der <bpmn:sequenceFlow> verbindet eine Task direkt mit einem Datenobjekt (<bpmn:dataObjectReference>).\n2. Semantischer Bruch des Kontrollflusses: Ein Sequenzfluss definiert, welche aktive Handlung als Nächstes ausgeführt wird. Ein Datenobjekt ist passiv und kann nicht "ausgeführt" werden.\n3. Missachtung der BPMN-Artefakte: Daten und Kontrollfluss sind in der BPMN strikt getrennte Konzepte und verwenden unterschiedliche XML-Elemente zur Verbindung.\nDidaktischer Hinweis: Datenobjekte, Datenspeicher und Annotationen dürfen niemals über einen Sequenzfluss (Sequence Flow) in den Prozessablauf integriert werden. Die Verbindung zwischen einer ausführenden Task und ihren Ein-/Ausgabedaten muss immer über Datenassoziationen (Data Associations) erfolgen.\nVerbesserungsvorschlag: Ersetzen Sie den <bpmn:sequenceFlow> durch eine <bpmn:dataOutputAssociation>. Diese wird innerhalb der Deklaration von Task_1 definiert und verweist mit <targetRef> auf das DataObject_1.',
    },
    {
        "question": 'Bewerte das folgende BPMN-Diagramm im XML-Format:\nxml\n<?xml version="1.0" encoding="UTF-8"?>\n<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL">\n <bpmn:process id="Process_Intern">\n <bpmn:task id="Task_A" name="Antrag prüfen" />\n <bpmn:task id="Task_B" name="Entscheidung eintragen" />\n <bpmn:messageFlow id="MsgFlow_1" sourceRef="Task_A" targetRef="Task_B" />\n </bpmn:process>\n</bpmn:definitions>',
        "ground_truth": 'Analyse:\n1. Message Flow innerhalb desselben Prozesses: Ein <bpmn:messageFlow> wird verwendet, um zwei Tasks innerhalb exakt desselben Prozesses ("Process_Intern") miteinander zu verbinden.\n2. Missachtung der Kommunikationsgrenzen: Message Flows dienen ausschließlich der Darstellung von Kommunikation (B2B-Nachrichten) zwischen unabhängigen Teilnehmern (verschiedenen Pools).\n3. Unklarer interner Kontrollfluss: Durch die fehlerhafte Nutzung der Nachrichtenverbindung fehlt dem System eine Definition über die tatsächliche zeitliche Ausführungsreihenfolge innerhalb der eigenen Organisation.\nDidaktischer Hinweis: Nachrichtenflüsse (Message Flows) sind strikt auf die externe Kommunikation beschränkt. Sie dürfen in BPMN niemals Elemente verknüpfen, die sich innerhalb ein und desselben Pools (oder hier: desselben Prozesses) befinden.\nVerbesserungsvorschlag: Ersetzen Sie den <bpmn:messageFlow> zwingend durch einen <bpmn:sequenceFlow>, um die interne, sequentielle Abarbeitung von "Task_A" und "Task_B" korrekt zu modellieren.',
    },
    {
        "question": 'Bewerte das folgende BPMN-Diagramm im XML-Format:\nxml\n<?xml version="1.0" encoding="UTF-8"?>\n<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL">\n <bpmn:process id="Process_1">\n <bpmn:task id="Task_A" />\n <bpmn:endEvent id="End_1">\n <bpmn:incoming>Flow_1</bpmn:incoming>\n <bpmn:outgoing>Flow_2</bpmn:outgoing>\n </bpmn:endEvent>\n <bpmn:task id="Task_B" />\n <bpmn:sequenceFlow id="Flow_1" sourceRef="Task_A" targetRef="End_1" />\n <bpmn:sequenceFlow id="Flow_2" sourceRef="End_1" targetRef="Task_B" />\n </bpmn:process>\n</bpmn:definitions>',
        "ground_truth": 'Analyse:\n1. Ausgehender Sequenzfluss an einem Endereignis: Das <bpmn:endEvent> besitzt das Tag <bpmn:outgoing>, welches den Kontrollfluss zu "Task_B" weiterleitet.\n2. Verletzung der Terminierungsregel: Ein Endereignis konsumiert das ankommende Token und beendet diesen Pfad des Prozesses. Es darf danach keinen Folgeablauf geben.\n3. Logischer Widerspruch: Die Semantik von "Ende" wird ad absurdum geführt, wenn danach weitere Aufgaben (Task_B) ausgeführt werden sollen.\nDidaktischer Hinweis: Gemäß der BPMN-Theorie sind Endereignisse reine Senken für den Kontrollfluss. Sie dürfen zwingend nur eingehende Sequenzflüsse (<incoming>) besitzen. Startereignisse sind Quellen (nur ausgehend), Endereignisse sind Senken (nur eingehend).\nVerbesserungsvorschlag: Entfernen Sie den ausgehenden Sequenzfluss (Flow_2) vom Endereignis. Wenn "Task_B" ausgeführt werden soll, muss "Task_A" mit "Task_B" verbunden werden, und "Task_B" führt anschließend in das Endereignis.',
    },
    {
        "question": 'Bewerte das folgende BPMN-Diagramm im XML-Format:\nxml\n<?xml version="1.0" encoding="UTF-8"?>\n<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL">\n <bpmn:process id="Process_1">\n <bpmn:exclusiveGateway id="XOR_Split" />\n <bpmn:task id="Task_A" />\n <bpmn:task id="Task_B" />\n <bpmn:sequenceFlow id="Flow_A" sourceRef="XOR_Split" targetRef="Task_A" />\n <bpmn:sequenceFlow id="Flow_B" sourceRef="XOR_Split" targetRef="Task_B" />\n </bpmn:process>\n</bpmn:definitions>',
        "ground_truth": 'Analyse:\n1. Fehlende Auswertungslogik: Die vom <bpmn:exclusiveGateway> ausgehenden Sequenzflüsse besitzen keine <bpmn:conditionExpression> (Bedingungen).\n2. Nicht-Determinismus im Modell: Ein XOR-Gateway muss exakt eine Entscheidung treffen. Ohne Bedingungen an den Kanten weiß die Process Engine (und der menschliche Leser) nicht, wann Pfad A und wann Pfad B gewählt werden soll.\n3. Fehlender Standardpfad: Es wurde auch kein Default-Fluss (Standardpfad) auf dem Gateway definiert, der als Fallback dient, falls keine Bedingung zutrifft.\nDidaktischer Hinweis: Ein datenbasiertes exklusives Gateway (XOR-Split) erfordert zwingend, dass alle ausgehenden Sequenzflüsse (bis auf maximal einen Default-Fluss) logische Bedingungen (Conditions) enthalten. Nur so ist der weitere Kontrollfluss determiniert.\nVerbesserungsvorschlag: Fügen Sie den Elementen Flow_A und Flow_B entsprechende <bpmn:conditionExpression>-Tags hinzu (z. B. "Wert > 100") oder deklarieren Sie einen der Flüsse im default-Attribut des Gateways.',
    },
    {
        "question": 'Bewerte das folgende BPMN-Diagramm im XML-Format:\nxml\n<?xml version="1.0" encoding="UTF-8"?>\n<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL">\n <bpmn:process id="Process_1">\n <bpmn:subProcess id="SubProcess_1">\n <bpmn:task id="SubTask_A" />\n <bpmn:task id="SubTask_B" />\n <bpmn:sequenceFlow id="Flow_Sub_1" sourceRef="SubTask_A" targetRef="SubTask_B" />\n </bpmn:subProcess>\n </bpmn:process>\n</bpmn:definitions>',
        "ground_truth": 'Analyse:\n1. Fehlendes Startereignis im Unterprozess: Der <bpmn:subProcess> enthält Tasks und einen Sequenzfluss, definiert aber keinen expliziten Startpunkt.\n2. Unklarer Instanziierungspunkt: Wenn der Unterprozess vom übergeordneten Prozess aufgerufen wird, ist formal nicht definiert, an welcher Aktivität der interne Kontrollfluss beginnen soll.\n3. Verletzung der Blockstruktur: Ein expandierter Unterprozess agiert wie ein eigener kleiner Prozess und muss einen vollständigen, validen Lebenszyklus (Start bis Ende) aufweisen.\nDidaktischer Hinweis: Jeder eingebettete Unterprozess (SubProcess) benötigt zwingend ein unbestimmtes Startereignis (None Start Event), um zu definieren, wo der interne Kontrollfluss beginnt, sobald das Token den SubProcess-Rahmen erreicht.\nVerbesserungsvorschlag: Ergänzen Sie innerhalb des <bpmn:subProcess> ein <bpmn:startEvent> und verbinden Sie es über einen internen Sequenzfluss mit der ersten Aufgabe "SubTask_A". Ein Endereignis sollte ebenfalls nach "SubTask_B" hinzugefügt werden.',
    },
    {
        "question": 'Bewerte das folgende BPMN-Diagramm im XML-Format:\nxml\n<?xml version="1.0" encoding="UTF-8"?>\n<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL">\n <bpmn:process id="Process_1">\n <bpmn:exclusiveGateway id="Gateway_1" />\n <bpmn:boundaryEvent id="Boundary_1" attachedToRef="Gateway_1">\n <bpmn:timerEventDefinition />\n </bpmn:boundaryEvent>\n </bpmn:process>\n</bpmn:definitions>',
        "ground_truth": 'Analyse:\n1. Fehlerhaft angeheftetes Randereignis: Ein <bpmn:boundaryEvent> wird über das Attribut attachedToRef="Gateway_1" an ein Gateway angeheftet.\n2. Semantischer Widerspruch: Gateways verbrauchen in der BPMN-Theorie keine Zeit, sie sind instantane Routing-Knoten. Daher kann es während ihrer Ausführung keinen Timeout oder Interrupt geben.\n3. Syntaxverletzung: Die BPMN-Spezifikation erlaubt das Anheften von Boundary Events ausschließlich an Aktivitäten (Tasks oder Unterprozesse).\nDidaktischer Hinweis: Angeheftete Zwischenereignisse (Boundary Events) dienen der Ausnahmebehandlung während der Laufzeit einer Aktivität. Da Gateways und Events eine Ausführungszeit von null (instant) haben, können sie niemals durch ein Boundary Event unterbrochen werden.\nVerbesserungsvorschlag: Ändern Sie das Attribut attachedToRef so, dass es auf eine valide <bpmn:task> oder einen <bpmn:subProcess> verweist, der tatsächlich Zeit beansprucht und durch einen Timer abgebrochen werden könnte.',
    },
    {
        "question": 'Bewerte das folgende BPMN-Diagramm im XML-Format:\nxml\n<?xml version="1.0" encoding="UTF-8"?>\n<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL">\n <bpmn:process id="Process_1">\n <bpmn:eventBasedGateway id="Event_Gateway_1" />\n <bpmn:task id="Task_Standard" name="Standardverarbeitung" />\n <bpmn:sequenceFlow id="Flow_1" sourceRef="Event_Gateway_1" targetRef="Task_Standard" />\n </bpmn:process>\n</bpmn:definitions>',
        "ground_truth": 'Analyse:\n1. Falsches Folgeelement nach ereignisbasiertem Gateway: Der Sequenzfluss führt von einem <bpmn:eventBasedGateway> direkt zu einer aktiven Aufgabe (<bpmn:task>).\n2. Logischer Funktionsbruch: Ein ereignisbasiertes Gateway dient dazu, den Kontrollfluss basierend darauf fortzusetzen, welches externe Ereignis zuerst eintritt (Race Condition). Es kann keine aktiven Handlungen auslösen.\n3. Formale Strukturverletzung: Gemäß BPMN 2.0 dürfen auf ein Event-Based Gateway ausschließlich Catching Events (z. B. Message, Timer) oder Receiver Tasks folgen.\nDidaktischer Hinweis: Das ereignisbasierte Gateway (Event-Based Gateway) pausiert den Prozess, bis eines von mehreren möglichen, externen Ereignissen eintritt. Daher müssen zwingend eintretende Zwischenereignisse (Catching Intermediate Events) direkt auf das Gateway folgen. Normale Tasks sind hier verboten.\nVerbesserungsvorschlag: Ersetzen Sie den <bpmn:task id="Task_Standard"> durch ein fangendes Ereignis, beispielsweise ein <bpmn:intermediateCatchEvent> mit einer Nachrichten- oder Timer-Definition, welches dann wiederum mit der eigentlichen Task verbunden wird.',
    },
    # --- Petri-Netz-Diagrammbewertung ---
    {
        "question": 'Bewerte das folgende Petri-Netz in PNML:\nxml\n<?xml version="1.0" encoding="UTF-8"?>\n<pnml>\n <net id="net1" type="ptnet">\n <place id="p1"><initialMarking><text>1</text></initialMarking></place>\n <place id="p2"/>\n <arc id="a1" source="p1" target="p2"/>\n </net>\n</pnml>',
        "ground_truth": 'Analyse:\n1. Verletzung der Bipartitheit: Das Diagramm verbindet die Stelle "p1" über eine Kante direkt mit der Stelle "p2".\n2. Fehlen eines aktiven Elements: Ein Systemzustand (Stelle) kann sich nicht von alleine in einen anderen Zustand verwandeln; es fehlt das auslösende Ereignis.\n3. Ungültige Graphstruktur: Nach der formalen Definition von Petri-Netzen ist diese Konstruktion syntaktisch und theoretisch absolut unzulässig.\nDidaktischer Hinweis: Ein Petri-Netz ist zwingend ein bipartiter Graph. Das bedeutet, dass Kanten immer nur zwischen Knoten unterschiedlichen Typs verlaufen dürfen (Stelle zu Transition oder Transition zu Stelle), niemals jedoch zwischen zwei Stellen oder zwei Transitionen.\nVerbesserungsvorschlag: Fügen Sie zwischen "p1" und "p2" eine Transition "t1" ein. Die Kanten müssen dann von "p1" zu "t1" und von "t1" zu "p2" verlaufen.',
    },
    {
        "question": 'Bewerte das folgende Bedingungs-Ereignis-Netz in PNML:\nxml\n<?xml version="1.0" encoding="UTF-8"?>\n<pnml>\n <net id="net1" type="ptnet">\n <place id="p_vor"><initialMarking><text>1</text></initialMarking></place>\n <place id="p_nach"><initialMarking><text>1</text></initialMarking></place>\n <transition id="t1"/>\n <arc id="a1" source="p_vor" target="t1"/>\n <arc id="a2" source="t1" target="p_nach"/>\n </net>\n</pnml>',
        "ground_truth": 'Analyse:\n1. Kontakt-Situation: Die Transition "t1" hat in ihrem Vorbereich eine markierte Stelle ("p_vor"), aber auch die Stelle im Nachbereich ("p_nach") ist bereits markiert.\n2. Blockierung der Transition: Gemäß den Schaltregeln für Bedingungs-Ereignis-Netze darf "t1" in diesem Zustand nicht feuern.\n3. Systemverklemmung: Obwohl die Vorbedingung für das Ereignis erfüllt ist, stagniert der Prozess, da der Zielzustand nicht frei ist.\nDidaktischer Hinweis: Eine Transition in einem reinen Bedingungs-Ereignis-Netz ist nur dann aktiviert (kann feuern), wenn alle Stellen im Vorbereich markiert UND alle Stellen im Nachbereich unmarkiert (frei) sind. Sind Nachbedingungen bereits belegt, spricht man von einem "Kontakt".\nVerbesserungsvorschlag: Entfernen Sie die initiale Markierung aus der Stelle "p_nach", damit das Ereignis "t1" ordnungsgemäß eintreten kann.',
    },
    {
        "question": 'Bewerte das folgende PNML-Modell, das explizit als "State Machine" (Finiter Zustandsautomat) konzipiert wurde:\nxml\n<?xml version="1.0" encoding="UTF-8"?>\n<pnml>\n <net id="net1" type="ptnet">\n <place id="p1"><initialMarking><text>1</text></initialMarking></place>\n <place id="p2"/>\n <place id="p3"/>\n <transition id="t1"/>\n <arc id="a1" source="p1" target="t1"/>\n <arc id="a2" source="t1" target="p2"/>\n <arc id="a3" source="t1" target="p3"/>\n </net>\n</pnml>',
        "ground_truth": 'Analyse:\n1. Unerlaubte Nebenläufigkeit: Die Transition "t1" erzeugt bei Ausführung gleichzeitig Marken in "p2" und "p3", was einen parallelen Kontrollfluss (Fork) darstellt.\n2. Verletzung der formalen Definition: Eine State Machine darf theoretisch keine Nebenläufigkeit abbilden.\n3. Verlust der Beschränktheit: Durch das Aufspalten vermehrt sich die Anzahl der Marken im System (aus 1 Marke werden 2), wodurch das System nicht mehr strikt 1-beschränkt ist.\nDidaktischer Hinweis: Ein Petri-Netz heißt "State Machine", wenn jede Transition genau eine eingehende und genau eine ausgehende Kante besitzt. Dadurch sind Konflikte möglich, aber Nebenläufigkeit ist strukturell ausgeschlossen.\nVerbesserungsvorschlag: Ändern Sie die Struktur. Entweder Sie trennen die Zielzustände durch separate Transitionen auf (Konflikt statt Parallelität), oder das Netz darf nicht als State Machine, sondern nur als allgemeines Petri-Netz klassifiziert werden.',
    },
    {
        "question": 'Bewerte das folgende Petri-Netz in PNML:\nxml\n<?xml version="1.0" encoding="UTF-8"?>\n<pnml>\n <net id="net1" type="ptnet">\n <place id="p1"/>\n <place id="p2"/>\n <transition id="t1"/>\n <transition id="t2"/>\n <arc id="a1" source="p1" target="t1"/>\n <arc id="a2" source="t1" target="p2"/>\n <arc id="a3" source="p2" target="t2"/>\n <arc id="a4" source="t2" target="p1"/>\n </net>\n</pnml>',
        "ground_truth": 'Analyse:\n1. Totale Verklemmung (Deadlock): Das Netz stellt einen geschlossenen Kreislauf dar, besitzt aber in keiner einzigen Stelle eine Anfangsmarkierung (Token).\n2. Keine Transition aktivierbar: Weder "t1" noch "t2" können jemals schalten, da ihre jeweiligen Vorbereiche völlig leer sind.\n3. Totes Netz: Der Erreichbarkeitsgraph dieses Netzes besteht nur aus dem leeren Zustand. Das System ist in der vorliegenden Form komplett nutzlos und theoretisch "tot".\nDidaktischer Hinweis: Damit ein Petri-Netz "lebendig" ist oder überhaupt arbeiten kann, benötigt es zwingend eine initiale Markierung (Systemzustand), die als Katalysator für die auszuführenden Ereignisse dient.\nVerbesserungsvorschlag: Fügen Sie der Stelle "p1" (oder "p2") eine initiale Marke hinzu: <initialMarking><text>1</text></initialMarking>, damit der Kreislauf starten kann.',
    },
    {
        "question": 'Bewerte das folgende Stellen/Transitionen-Netz in PNML bezüglich seiner Beschränktheit:\nxml\n<?xml version="1.0" encoding="UTF-8"?>\n<pnml>\n <net id="net1" type="ptnet">\n <place id="p1"><initialMarking><text>1</text></initialMarking></place>\n <transition id="t1"/>\n <arc id="a1" source="p1" target="t1"><inscription><text>1</text></inscription></arc>\n <arc id="a2" source="t1" target="p1"><inscription><text>2</text></inscription></arc>\n </net>\n</pnml>',
        "ground_truth": 'Analyse:\n1. Unendliches Marken-Wachstum: Die Transition "t1" verbraucht beim Schalten 1 Marke aus "p1", legt aber anschließend 2 Marken in "p1" zurück.\n2. Verletzung der k-Beschränktheit: Bei jedem Schalten erhöht sich die Gesamtanzahl der Marken im Netz um 1. Es gibt keine Obergrenze (k), die nie überschritten wird.\n3. Unendlicher Erreichbarkeitsgraph: Da die Anzahl der Marken theoretisch gegen unendlich wächst, lässt sich kein endlicher Zustandsraum für dieses System abbilden.\nDidaktischer Hinweis: Ein Petri-Netz ist k-beschränkt, wenn keine Stelle jemals mehr als k Marken gleichzeitig enthält. Unbeschränkte Netze deuten in der Praxis oft auf Fehler hin (z. B. unendliche Warteschlangen oder explodierende Ressourcen), da reale Systeme immer endliche Kapazitäten haben.\nVerbesserungsvorschlag: Balancieren Sie die Kantengewichte (Inscription), sodass Verbrauch und Erzeugung im Gleichgewicht sind (z. B. beide auf 1), oder ergänzen Sie eine Kapazitätsgrenze für die Stelle "p1".',
    },
    {
        "question": 'Bewerte das folgende als "Marked Graph" (Markierter Graph) intendierte Petri-Netz in PNML:\nxml\n<?xml version="1.0" encoding="UTF-8"?>\n<pnml>\n <net id="net1" type="ptnet">\n <place id="p1"><initialMarking><text>1</text></initialMarking></place>\n <transition id="t1"/>\n <transition id="t2"/>\n <arc id="a1" source="p1" target="t1"/>\n <arc id="a2" source="p1" target="t2"/>\n </net>\n</pnml>',
        "ground_truth": 'Analyse:\n1. Vorhandensein eines Konflikts: Die Stelle "p1" besitzt zwei ausgehende Kanten, die zu den Transitionen "t1" und "t2" führen. Da nur eine Marke vorhanden ist, stehen die Transitionen in direkter Konkurrenz.\n2. Verletzung der Definition: Ein Petri-Netz darf sich theoretisch nur dann "Marked Graph" nennen, wenn jede Stelle genau eine eingehende und genau eine ausgehende Kante besitzt.\n3. Falscher Anwendungszweck: Marked Graphs dienen ausschließlich der Modellierung von Nebenläufigkeit und Synchronisation, nicht jedoch für Entscheidungen oder Konflikte.\nDidaktischer Hinweis: In der Petri-Netz-Theorie sind in einem Markierten Graphen (Marked Graph) Konflikte strukturell ausgeschlossen. Sobald eine Stelle mehr als eine ausgehende Kante hat, handelt es sich lediglich um ein allgemeines Stellen/Transitionen-Netz oder ein Free Choice Net.\nVerbesserungsvorschlag: Entfernen Sie die Kante zu "t2", sodass "p1" nur noch exakt eine ausgehende Kante zu "t1" besitzt, um die Eigenschaften eines Marked Graphs zu erfüllen.',
    },
    {
        "question": 'Bewerte das folgende Petri-Netz in PNML hinsichtlich seiner Lebendigkeit:\nxml\n<?xml version="1.0" encoding="UTF-8"?>\n<pnml>\n <net id="net1" type="ptnet">\n <place id="p1"><initialMarking><text>1</text></initialMarking></place>\n <place id="p2"/>\n <transition id="t1"/>\n <arc id="a1" source="p1" target="t1"/>\n <arc id="a2" source="p2" target="t1"/>\n </net>\n</pnml>',
        "ground_truth": 'Analyse:\n1. Unerfüllbare Vorbedingung: Die Transition "t1" benötigt zum Schalten zwingend Marken aus beiden Stellen ihres Vorbereichs ("p1" und "p2").\n2. Tote Transition: Die Stelle "p2" ist unmarkiert und besitzt keinerlei eingehende Kanten. Sie kann folglich niemals im Laufe des Prozesses eine Marke erhalten.\n3. Verletzung der starken Lebendigkeit: Da "t1" unter keiner einzigen erreichbaren Folgemarkierung jemals aktiviert werden kann, ist die Transition "tot", und das gesamte Netz ist somit nicht stark lebendig.\nDidaktischer Hinweis: Eine Transition heißt tot, wenn sie bei keinem der möglichen Folgezustände jemals wieder schalten kann. Stellen ohne eingehende Kanten und ohne Anfangsmarkierung blockieren alle nachfolgenden Ereignisse dauerhaft.\nVerbesserungsvorschlag: Weisen Sie der Stelle "p2" eine initiale Markierung zu (<initialMarking><text>1</text></initialMarking>) oder fügen Sie eine vorgeschaltete Transition hinzu, die "p2" mit Marken versorgen kann.',
    },
    {
        "question": 'Bewerte das folgende Petri-Netz in PNML, das als "Free Choice Net" (Freie-Wahl-Netz) deklariert ist:\nxml\n<?xml version="1.0" encoding="UTF-8"?>\n<pnml>\n <net id="net1" type="ptnet">\n <place id="p1"><initialMarking><text>1</text></initialMarking></place>\n <place id="p2"><initialMarking><text>1</text></initialMarking></place>\n <transition id="t1"/>\n <transition id="t2"/>\n <arc id="a1" source="p1" target="t1"/>\n <arc id="a2" source="p1" target="t2"/>\n <arc id="a3" source="p2" target="t1"/>\n </net>\n</pnml>',
        "ground_truth": 'Analyse:\n1. Asymmetrischer Konflikt: Die Transition "t1" benötigt Marken aus "p1" und "p2". Die Transition "t2" benötigt jedoch nur eine Marke aus "p1".\n2. Verletzung der Freie-Wahl-Regel: In einem Free Choice Net muss die Wahl zwischen zwei Transitionen (hier "t1" und "t2", die sich "p1" teilen) völlig unabhängig vom restlichen Netz sein. Hier ist die Wahl jedoch vom Zustand von "p2" abhängig.\n3. Keine eFCN-Eigenschaft: Auch die Definition für ein Extended Free Choice Net (eFCN) ist verletzt, da nicht alle Stellen aus dem Vorbereich von "t1" ("p1", "p2") mit allen Transitionen im Nachbereich von "p1" ("t1", "t2") verbunden sind.\nDidaktischer Hinweis: Die namensgebende Regel für ein Free Choice Net besagt: Wenn eine Kante von einer Stelle zu einer Transition führt, muss sie entweder die einzige ausgehende Kante dieser Stelle ODER die einzige eingehende Kante dieser Transition sein.\nVerbesserungsvorschlag: Fügen Sie eine Kante von "p2" zu "t2" hinzu (<arc id="a4" source="p2" target="t2"/>). Dadurch wird das Netz zu einem Extended Free Choice Net (eFCN), bei dem die Konfliktentscheidung wieder symmetrisch ist.',
    },
    {
        "question": 'Bewerte das folgende Petri-Netz in PNML bezüglich seines Ressourcenflusses:\nxml\n<?xml version="1.0" encoding="UTF-8"?>\n<pnml>\n <net id="net1" type="ptnet">\n <place id="p1"><initialMarking><text>1</text></initialMarking></place>\n <place id="p_senke"/>\n <transition id="t1"/>\n <arc id="a1" source="p1" target="t1"/>\n <arc id="a2" source="t1" target="p_senke"/>\n </net>\n</pnml>',
        "ground_truth": 'Analyse:\n1. Existenz einer reinen Senkenstelle: Die Stelle "p_senke" besitzt eine eingehende Kante von "t1", aber keinerlei ausgehende Kanten zu weiteren Transitionen.\n2. Unvermeidlicher Ressourcenverlust (Trap-Wirkung): "p_senke" agiert als ultimativer Trap (Falle). Jede Marke, die dort hineinfällt, kann das System nie wieder verlassen oder für weitere Prozesse genutzt werden.\n3. Fehlende Reversibilität: Das System kann nach dem Feuern von "t1" unmöglich in seinen Anfangszustand (Marke auf "p1") zurückkehren.\nDidaktischer Hinweis: Ein Petri-Netz ist reversibel (rücksetzbar), wenn es aus jedem erreichbaren Zustand wieder in seinen Anfangszustand zurückkehren kann. Senken (Stellen ohne Ausgang) oder Quellen (Transitionen ohne Eingang) verhindern die Reversibilität und modellieren oft unvollständige Systemkreisläufe.\nVerbesserungsvorschlag: Fügen Sie eine Transition "t_reset" hinzu, die eine Kante von "p_senke" zu "t_reset" und eine Kante von "t_reset" zurück zu "p1" besitzt, um das Netz zyklisch und reversibel zu machen.',
    },
    {
        "question": 'Bewerte das folgende Petri-Netz in PNML:\nxml\n<?xml version="1.0" encoding="UTF-8"?>\n<pnml>\n <net id="net1" type="ptnet">\n <place id="p1"/>\n <transition id="t_quelle"/>\n <arc id="a1" source="t_quelle" target="p1"/>\n </net>\n</pnml>',
        "ground_truth": 'Analyse:\n1. Quelltransition ohne Vorbedingung: Die Transition "t_quelle" besitzt keine eingehenden Kanten (keinen Vorbereich).\n2. Dauerhafte Aktivierung: Gemäß den Schaltregeln ist eine Transition aktiviert, wenn alle ihre Vorbedingungen erfüllt sind. Da es hier keine Vorbedingungen gibt, ist "t_quelle" permanent und bedingungslos aktiviert.\n3. Unendliche Markenproduktion: "t_quelle" kann unendlich oft feuern und füllt die Stelle "p1" mit unendlich vielen Marken, was das Netz radikal unbeschränkt macht (Zustandsexplosion).\nDidaktischer Hinweis: Transitionen ohne Vorbereich werden als "Quelltransitionen" bezeichnet. In praktischen Modellierungen (abseits von reinen Theoriekonstrukten) deuten sie meist auf Modellierungsfehler hin, da in geschlossenen Systemen Aktionen immer durch bestimmte Bedingungen oder Ressourcen limitiert sein sollten.\nVerbesserungsvorschlag: Fügen Sie eine Stelle in den Vorbereich von "t_quelle" ein, die mit einer endlichen Kapazität an Marken (z. B. "Rohmaterial") initialisiert wird, um die Anzahl der Schaltvorgänge zu begrenzen.',
    },
    # --- UML-Diagrammbewertung ---
    {
        "question": 'Bewerte das folgende UML-Anwendungsfalldiagramm:\nplantuml\n@startuml\nactor Kunde\nusecase "Pizza bestellen" as UC1\nusecase "Extra Käse hinzufügen" as UC2\nKunde --> UC1\nUC1 ..> UC2 : <<include>>\n@enduml',
        "ground_truth": 'Analyse:\n1. Falscher Stereotyp für optionale Abläufe: Das Hinzufügen von extra Käse ist eine Option, kein zwingender Bestandteil. Das Stereotyp <<include>> erzwingt jedoch theoretisch die Ausführung bei jedem einzelnen Durchlauf der Bestellung.\n2. Verletzung der Wiederverwendbarkeit: Die Include-Beziehung wird in der UML genutzt, um redundantes, zwingendes Verhalten (wie Authentifizierung) auszulagern, nicht für fachliche Varianten eines Prozesses.\n3. Umkehrung der Abhängigkeit: Bei optionalen Varianten sollte der Basis-Anwendungsfall unabhängig bleiben. Hier wird er durch das Include fälschlicherweise strukturell abhängig von der Erweiterung gemacht.\nDidaktischer Hinweis: Die UML-Theorie unterscheidet strikt zwischen zwingender Inklusion (Include, Pfeil zeigt zum ausgelagerten Use Case) und bedingter Erweiterung (Extend, Pfeil zeigt zurück zum Basis-Use Case). Optionale Varianten müssen zwingend mit Extend modelliert werden.\nVerbesserungsvorschlag: Ändern Sie die Beziehung in eine Extend-Beziehung und drehen Sie die Pfeilrichtung um, sodass der erweiternde Use Case auf den Basis-Use Case zeigt: UC2 ..> UC1 : <<extend>>.',
    },
    {
        "question": 'Bewerte das folgende UML-Klassendiagramm:\nplantuml\n@startuml\nclass Gebaeude {\n - adresse: String\n}\nclass Raum {\n - quadratmeter: int\n}\nGebaeude <|-- Raum\n@enduml',
        "ground_truth": 'Analyse:\n1. Verletzung der "Ist-ein"-Semantik: Die Generalisierung (Vererbung) bedeutet "Ein Raum ist ein Gebäude", was theoretisch und fachlich falsch ist.\n2. Fehlerhafte Vererbung von Attributen: Durch die Generalisierung erbt der Raum fälschlicherweise die Attribute der Oberklasse. Jeder Raum hätte dadurch logisch eine eigene Gebäudeadresse.\n3. Missachtung der Teil-Ganzes-Beziehung: Räume sind physische, existenzabhängige Bestandteile eines Gebäudes, was in der objektorientierten Modellierung ein völlig anderes Strukturkonzept erfordert als die Vererbung.\nDidaktischer Hinweis: In der objektorientierten Theorie darf Vererbung (Generalisierung) ausschließlich für taxonomische Spezialisierungen (Kategorisierungen) genutzt werden. Die Modellierung von strukturellen Zugehörigkeiten ("Besteht-aus") muss über Assoziationen erfolgen.\nVerbesserungsvorschlag: Ersetzen Sie den Vererbungspfeil durch eine Komposition (gefüllte Raute am Gebäude), da ein Raum physisch existenzabhängig vom Gebäude ist: Gebaeude "1" -- "1.." Raum.',
    },
    {
        "question": 'Bewerte das folgende UML-Aktivitätsdiagramm:\nplantuml\n@startuml\nstart\nif (Zahlungsart?) then (Rechnung)\n :Bonität prüfen;\nelse (Kreditkarte)\n :Limit prüfen;\nendif\nfork\n :Ware versenden;\n :Rechnung drucken;\nend fork\nstop\n@enduml',
        "ground_truth": 'Analyse:\n1. Fehlender Merge-Knoten: Die exklusive Verzweigung (XOR, Raute) wird nicht sauber durch einen entsprechenden Verbindungsknoten zusammengeführt, bevor der parallele Bereich beginnt.\n2. Theoretische Deadlock-Gefahr: Ein impliziter Join (Synchronisation) vor dem Fork würde auf Tokens aus beiden if-Pfaden warten. Da die Raute eine Entweder-Oder-Entscheidung erzwingt, entsteht ein Deadlock.\n3. Unsaubere Vermischung von Kontrollflusslogiken: Alternativer Kontrollfluss (XOR) und paralleler Kontrollfluss (AND) werden ohne explizite Übergabe der Tokens fehlerhaft hintereinandergeschaltet.\nDidaktischer Hinweis: Nach den Regeln der UML müssen sich aufspaltende Kontrollflüsse zwingend durch die logisch passenden Knoten wieder zusammenführen (XOR-Split erfordert XOR-Merge, AND-Split erfordert AND-Join).\nVerbesserungsvorschlag: Fügen Sie nach den beiden Prüf-Aktivitäten einen expliziten Merge-Knoten (Raute) ein, der die alternativen Pfade zusammenführt, bevor der parallele Fork-Block für Versand und Druck gestartet wird.',
    },
    {
        "question": 'Bewerte das folgende UML-Zustandsdiagramm:\nplantuml\n@startuml\n[*] --> WartenAufKunde\nWartenAufKunde --> PINPruefen\nPINPruefen --> WartenAufKunde : abbruch\n@enduml',
        "ground_truth": 'Analyse:\n1. Spontane Transition aus einem Wartezustand: Die Transition von "WartenAufKunde" zu "PINPruefen" besitzt keinen Trigger (Ereignis). Das System würde diesen Wartezustand sofort und automatisch wieder verlassen.\n2. Verletzung der Zustandssicherheit: "WartenAufKunde" ist semantisch ein passiver Zustand, der auf eine externe Eingabe warten muss, was theoretisch zwingend ein auslösendes Event erfordert.\n3. Unvollständige Spezifikation: Es fehlt die theoretische Definition, welches Signal des Akteurs (z.B. das Einführen der Karte) den Zustandswechsel und damit die Aktion überhaupt legitimiert.\nDidaktischer Hinweis: In Zustandsautomaten feuern Transitionen ohne Event-Label (spontane Transitionen) automatisch nach Abschluss der internen Aktivitäten. Passive Wartezustände benötigen daher immer einen definierten Auslöser (Trigger), um ein Verweilen im Zustand zu erzwingen.\nVerbesserungsvorschlag: Fügen Sie der ausgehenden Transition aus "WartenAufKunde" das korrekte auslösende Ereignis als Label hinzu, z. B.: WartenAufKunde --> PINPruefen : karteEingesteckt.',
    },
    {
        "question": 'Bewerte das folgende UML-Klassendiagramm:\nplantuml\n@startuml\nclass Bankkonto {\n + kontostand: double\n + pin: int\n + abheben(betrag: double)\n}\n@enduml',
        "ground_truth": 'Analyse:\n1. Verletzung der Kapselung (Information Hiding): Kritische Attribute wie "kontostand" und "pin" sind als "public" (+) deklariert, was theoretisch direkten Lese- und Schreibzugriff von außen durch jede andere Klasse erlaubt.\n2. Fehlen von Schnittstellenkontrolle: Die Integrität des Kontos ist gefährdet, da der Kontostand ohne die Validierungslogik der Methode "abheben" beliebig von außen verändert werden kann.\n3. Mangelhafte Abstraktion: Interne Zustandsvariablen einer Klasse sollten in der objektorientierten Theorie für externe Aufrufer unsichtbar sein.\nDidaktischer Hinweis: Das Kernprinzip der Datenkapselung (Encapsulation) fordert, dass der interne Zustand eines Objekts vor unkontrolliertem externem Zugriff geschützt wird. Datenattribute sollten standardmäßig "private" (-) sein, Manipulationen erfolgen über "public" (+) Methoden.\nVerbesserungsvorschlag: Ändern Sie die Sichtbarkeiten der Attribute "kontostand" und "pin" zwingend von public (+) auf private (-). Die Zustandsänderung darf ausschließlich über die Methode abheben() erfolgen.',
    },
    {
        "question": 'Bewerte das folgende UML-Anwendungsfalldiagramm:\nplantuml\n@startuml\nrectangle "Buchungssystem" {\n actor "Zahlungs-API" as api\n usecase "Zahlung verarbeiten" as uc1\n api --> uc1\n}\n@enduml',
        "ground_truth": 'Analyse:\n1. Verletzung der Systemgrenze: Der Akteur "Zahlungs-API" wurde innerhalb des Rechtecks (System Boundary) modelliert. Akteure müssen sich nach UML-Theorie jedoch zwingend außerhalb der Systemgrenzen befinden.\n2. Missverständnis des Akteur-Konzepts: Ein Akteur repräsentiert in der UML externe Systeme, Personen oder Hardware, die nicht Teil der Systemimplementierung sind.\n3. Unklare Systemverantwortung: Wenn die Zahlungs-API Teil des Systems wäre, dürfte sie kein Akteur sein, sondern müsste als interne Komponente modelliert werden, die den Anwendungsfall ausführt.\nDidaktischer Hinweis: Das Systemgrenzen-Rechteck (System Boundary) trennt streng zwischen dem, was das System ist (Anwendungsfälle im Inneren), und dem, was mit dem System interagiert (Akteure außerhalb). Ein Akteur darf nie im System liegen.\nVerbesserungsvorschlag: Verschieben Sie den Akteur "Zahlungs-API" aus dem Rechteck heraus. Die Assoziationslinie darf die Systemgrenze überschreiten, der Akteur jedoch nicht.',
    },
    {
        "question": 'Bewerte das folgende UML-Sequenzdiagramm:\nplantuml\n@startuml\nactor Kunde\nparticipant Webshop\nKunde --> Webshop: Artikel suchen()\nWebshop -> Kunde: Suchergebnis\n@enduml',
        "ground_truth": 'Analyse:\n1. Falscher Pfeiltyp für synchrone Nachrichten: Die initiierende Nachricht "Artikel suchen()" wird fälschlicherweise als Antwort (gestrichelter Pfeil -->) dargestellt.\n2. Umkehrung der UML-Semantik: Der synchrone Methodenaufruf des Kunden an das System muss mit einem durchgezogenen Pfeil gezeichnet werden, während das Systemergebnis als Return-Nachricht gestrichelt sein müsste.\n3. Fehlende Kontrollfluss-Klarheit: Ohne korrekte Unterscheidung von Call und Return ist nicht erkennbar, wer den Kontrollfluss steuert und wer auf die Abarbeitung blockierend wartet.\nDidaktischer Hinweis: In der UML-Theorie repräsentieren durchgezogene Pfeile mit geschlossener Spitze Aufrufe (Calls), bei denen der Sender die Ausführung initiiert. Gestrichelte Pfeile mit offener Spitze repräsentieren die Rückgabe der Kontrolle (Return) nach Beendigung der Ausführung.\nVerbesserungsvorschlag: Tauschen Sie die Pfeiltypen: Kunde -> Webshop: Artikel suchen() (durchgezogen) für den Aufruf und Webshop --> Kunde: Suchergebnis (gestrichelt) für die Antwort.',
    },
    {
        "question": 'Bewerte das folgende UML-Klassendiagramm:\nplantuml\n@startuml\nclass Buch {\n - titel: String\n}\nclass Kapitel {\n - ueberschrift: String\n}\nBuch "1" o-- "1..*" Kapitel\n@enduml',
        "ground_truth": 'Analyse:\n1. Zu schwache Teil-Ganzes-Beziehung: Die gewählte Aggregation (hohle Raute) impliziert, dass ein Kapitel auch eigenständig, unabhängig von einem Buch existieren kann, was in diesem Kontext theoretisch keinen Sinn ergibt.\n2. Verletzung der Lebensdauer-Abhängigkeit: Wenn ein Buch zerstört wird, werden logischerweise auch seine Kapitel vernichtet. Diese existenzielle Abhängigkeit kann von der Aggregation nicht ausgedrückt werden.\n3. Fehlen der Exklusivität: Ein Kapitel kann fachlich immer nur zu genau einem bestimmten Buch gehören. Die Aggregation erlaubt theoretisch das Teilen von Objekten (Shared Aggregation).\nDidaktischer Hinweis: Die UML unterscheidet bei Assoziationen streng zwischen loser Zugehörigkeit (Aggregation) und strenger Existenzabhängigkeit (Komposition). Teile, die ohne das Ganze keinen Sinn ergeben und mit ihm vernichtet werden, erfordern zwingend eine Komposition.\nVerbesserungsvorschlag: Ändern Sie die hohle Raute der Aggregation in eine gefüllte Raute (Komposition), um die starke existentielle Abhängigkeit auszudrücken: Buch "1" *-- "1..*" Kapitel.',
    },
    {
        "question": 'Bewerte das folgende UML-Aktivitätsdiagramm:\nplantuml\n@startuml\nstart\n:Prozess starten;\nif (Typ A?) then (ja)\n :Typ A verarbeiten;\nstop\nelse (nein)\n :Typ B verarbeiten;\n :Prozess abschließen;\nstop\nendif\n@enduml',
        "ground_truth": 'Analyse:\n1. Syntax- und Strukturfehler bei Endknoten: Das Platzieren von stop-Knoten (Ablaufende) direkt innerhalb der if/else-Zweige verhindert die ordnungsgemäße Zusammenführung des Kontrollflusses.\n2. Verletzung der Blockstruktur: Ein Bedingungsblock in der UML ist ein strukturierter Knoten, der theoretisch einen sauberen Eingang (Split) und einen sauberen Ausgang (Merge) besitzen muss, bevor der Prozess beendet wird.\n3. Redundanz bei Terminierung: Anstatt das System mehrfach unsauber in Unterpfaden abzubrechen, sollte der Kontrollfluss zentralisiert beendet werden, um Nebeneffekte (wie hängende Tokens) zu vermeiden.\nDidaktischer Hinweis: Aktivitätsdiagramme sollten sich an den Prinzipien der strukturierten Programmierung orientieren (Single Entry, Single Exit für Kontrollblöcke). Endknoten mitten in bedingten Ästen erschweren die Lesbarkeit und Wiederverwendbarkeit des Diagramms.\nVerbesserungsvorschlag: Führen Sie die Verzweigung erst sauber mit endif zusammen (Merge) und setzen Sie genau einen gemeinsamen stop-Knoten an das Ende des gesamten Prozesses.',
    },
    {
        "question": 'Bewerte das folgende UML-Zustandsdiagramm:\nplantuml\n@startuml\n[*] --> Eingeschaltet\nEingeschaltet --> Ausgeschaltet : ausschalten\nAusgeschaltet --> [*]\n@enduml',
        "ground_truth": 'Analyse:\n1. Finaler Zustand blockiert Wiederverwendung: Das Gerät wechselt nach dem Ausschalten direkt in den finalen Endzustand [*]. Dies bedeutet in der UML-Theorie, dass das Objekt vernichtet wird und nicht mehr existiert.\n2. Fehlende Zyklizität: Ein normales elektronisches Gerät kann mehrfach ein- und ausgeschaltet werden. Dies wird hier unterbunden.\n3. Verwechslung von "Zustand" und "Lebensende": "Ausgeschaltet" ist ein legitimer, stabiler Zustand eines existierenden Objekts, kein Grund zur Terminierung des Objekts selbst im Speicher.\nDidaktischer Hinweis: Der Endknoten (Bullseye, in PlantUML auf der rechten Pfeilseite als [*] dargestellt) bedeutet nicht einfach "Prozess fertig", sondern markiert das Ende des Lebenszyklus (Destruktion) des Objekts, dessen Zustände hier modelliert werden.\nVerbesserungsvorschlag: Entfernen Sie den Übergang zum Endzustand. Fügen Sie stattdessen eine Transition hinzu, die das Wiedereinschalten ermöglicht: Ausgeschaltet --> Eingeschaltet : einschalten. Ein Endknoten ist für langlebige Objekte oft gar nicht nötig.',
    },
]
